use std::fs;

pub fn list(root: &str) -> Result<Vec<(i32, String)>, i32> {
    let mut files = Vec::new();
    let entries = fs::read_dir(root).map_err(|_| 1)?;
    for entry in entries {
        let entry = entry.map_err(|_| 1)?;
        let kind = entry.file_type().map_err(|_| 1)?;
        if !kind.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        let bytes = name.as_bytes();
        if bytes.len() != 13 || bytes[0] != b'd' || &name[9..] != ".tbl"
            || !bytes[1..9].iter().all(u8::is_ascii_digit)
        {
            continue;
        }
        let day = name[1..9].parse::<i32>().map_err(|_| 1)?;
        files.push((day, entry.path().to_string_lossy().into_owned()));
    }
    files.sort_by_key(|item| item.0);
    Ok(files)
}

pub fn nlines(path: &str) -> Result<i32, i32> {
    let text = fs::read_to_string(path).map_err(|_| 1)?;
    let count = text.lines().filter(|line| !line.trim().is_empty()).count();
    i32::try_from(count).map_err(|_| 1)
}
EOF
